export async function getProductInventory(productId: number): Promise<ProductStockInfo | false> {
    // Validate product exists and is the right type (excludes combos, GVs, freebies, parent products)
    const productRows = await db
        .select({ parentProdId: products.parentProdId, isAvail: products.isAvail, isDel: products.isDel })
        .from(products)
        .where(and(
            eq(products.id, productId),
            inArray(products.prodType, [PRODUCT_TYPES.SIMPLE, PRODUCT_TYPES.MEMBERSHIP, PRODUCT_TYPES.FREEBIE, PRODUCT_TYPES.GIFT_VOUCHER])
        ))
        .limit(1);

    if (productRows.length === 0) return false;

    const p = productRows[0];

    // Fetch stock and stocked (buffer) from product_stocks table
    const stockRows = await db
        .select({ stock: productStocks.stock, stocked: productStocks.stocked })
        .from(productStocks)
        .where(eq(productStocks.prodId, productId))
        .limit(1);

    // Fetch warehouse stocks from product_store joined with stores
    const warehouseRows = await db
        .select({ locationCode: stores.locationCode, stock: productStore.stock })
        .from(productStore)
        .innerJoin(stores, eq(productStore.storeId, stores.id))
        .where(and(
            eq(productStore.productId, productId),
            inArray(stores.locationCode, WAREHOUSE_LOCATIONS)
        ));

    // Build warehouse stock map for easy lookup
    const warehouseStockMap: { [key: string]: number } = {};
    for (const row of warehouseRows) {
        warehouseStockMap[row.locationCode.toLowerCase()] = row.stock || 0;
    }

    // Calculate store online stock (stock above ecommerce threshold from delivery-enabled stores)
    const storeRows = await db
        .select({ sum: sum(sql`${productStore.stock} - ${stores.ecomThreshold}`) })
        .from(productStore)
        .leftJoin(stores, eq(productStore.storeId, stores.id))
        .where(and(
            eq(productStore.productId, productId),
            eq(stores.ecomDelivery, 1),
            gt(productStore.stock, 0),
            sql`${productStore.stock} > ${stores.ecomThreshold}`
        ));

    const storeOnline = parseInt(storeRows[0].sum || '0', 10);

    // Return comprehensive inventory object with all warehouse stocks from product_store
    return {
        parentProductId: p.parentProdId || 0,
        totalOnline: (stockRows.length > 0 ? stockRows[0].stock || 0 : 0),  // From product_stocks table
        storeOnline,
        buffer: (stockRows.length > 0 ? stockRows[0].stocked || 0 : 0),  // From product_stocks table
        isAvail: p.isAvail,
        isDel: p.isDel,
        dwh: warehouseStockMap['dwh'] || 0,
        bwh: warehouseStockMap['bwh'] || 0,
        wwh: warehouseStockMap['wwh'] || 0,
        bw1: warehouseStockMap['bw1'] || 0,
        bw2: warehouseStockMap['bw2'] || 0,
        dw1: warehouseStockMap['dw1'] || 0,
        hwh: warehouseStockMap['hwh'] || 0,
        mw1: warehouseStockMap['mw1'] || 0,
        mw2: warehouseStockMap['mw2'] || 0,
        mw3: warehouseStockMap['mw3'] || 0,
    };
}

